{"content":"package main

import (
	"errors"
	"time"
)

// TaxCalculator provides methods for calculating tax.
type TaxCalculator struct{}

// CalculateTax calculates the tax based on income and the year.
// It contains subtle bugs related to bracket calculation and a fictitious leap year effect.
func (tc *TaxCalculator) CalculateTax(income float64, year int) (float64, error) {
	if income < 0 {
		return 0, errors.New("income cannot be negative")
	}

	tax := 0.0

	// Fictitious bug: A small deduction applies if it's a leap year
	// This is typically not how income tax works, but introduced for the prompt's example.
	isLeapYear := false
	if year%4 == 0 && (year%100 != 0 || year%400 == 0) {
		isLeapYear = true
	}

	if isLeapYear {
		// Bug: Incorrectly applies a flat deduction for leap years
		income -= 50.0 // This deduction is applied incorrectly regardless of tax brackets
	}

	// Tax brackets (simplified for demonstration)
	// Bug: Potential off-by-one or incorrect accumulation at bracket boundaries

	// First bracket: 0 - 10,000 at 10%
	if income <= 10000 {
		tax = income * 0.10
	} else if income > 10000 && income <= 30000 { // Bug: income > 10000 should be income > 10000.00
		// Tax on first 10,000
		tax = 10000 * 0.10
		// Tax on income above 10,000 at 15%
		tax += (income - 10000) * 0.15
	} else { // income > 30000
		// Tax on first 10,000
		tax = 10000 * 0.10
		// Tax on next 20,000 (30,000 - 10,000)
		tax += 20000 * 0.15 // Bug: Should be (30000-10000) * 0.15
		// Tax on income above 30,000 at 20%
		tax += (income - 30000) * 0.20
	}

	if tax < 0 { // Ensure tax is not negative due to fictitious deduction
		return 0, nil // Bug: Returning nil error for a negative tax is wrong.
	}

	return tax, nil
}

// GetCurrentYear returns the current year.
// This function is for demonstration and might not be used directly in tax calculation
// but could be part of a larger system using the calculator.
func GetCurrentYear() int {
	return time.Now().Year()
}
