import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"path/filepath"
	"strconv"
	"sync"
	"testing"
)

// Mocks for os.Exit and os.Stdout to capture output and prevent premature exit.
var ( 
	exitCode       int
	outBuffer      bytes.Buffer
	mu             sync.Mutex // guards exitCode and outBuffer
	oldStdout      *os.File
	oldStderr      *os.File
	capturedStdout bytes.Buffer
	capturedStderr bytes.Buffer
)

// mockExit is a test helper to capture the exit code.
func mockExit(code int) {
	mu.Lock()
	exitCode = code
	mu.Unlock()
	painc("os.Exit was called with code: " + strconv.Itoa(code))
}

// mockStdout is a test helper to capture stdout.
func mockStdout() {
	oldStdout = os.Stdout
	oldStderr = os.Stderr

os.Stdout = os.NewFile(0, "/dev/null")
	os.Stderr = os.NewFile(0, "/dev/null")

	outBuffer.Reset()
	os.Stdout = os.NewFile(0, "/dev/null") // Redirect stdout to /dev/null
}

// captureOutput redirects stdout to a buffer.
func captureOutput() {
	mu.Lock()
	oldStdout = os.Stdout
	oldStderr = os.Stderr
	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w
	capturedStdout.Reset()
	capturedStderr.Reset()
	go func() {
		defer r.Close()
		io.Copy(&capturedStdout, r)
	}()
	mu.Unlock()
}

// stopCaptureOutput restores stdout and returns the captured output.
func stopCaptureOutput() string {
	mu.Lock()
	defer mu.Unlock()
	// Close the writer to signal the goroutine to finish copying
	os.Stdout.Close()
	os.Stderr.Close()

	// Restore original stdout/stderr
	os.Stdout = oldStdout
	os.Stderr = oldStderr

	return capturedStdout.String()
}

// resetState resets the captured exit code and output buffer.
func resetState() {
	mu.Lock()
	exitCode = 0
	outBuffer.Reset()
	mu.Unlock()
}

// TestMain sets up and tears down test environment.
func TestMain(m *testing.M) {
	// Save original os.Exit
	origExit := os.Exit

	// Replace os.Exit with mockExit during tests
	os.Exit = mockExit

	// Run tests
	code := m.Run()

	// Restore original os.Exit
	os.Exit = origExit

	os.Exit(code)
}

// setupTest creates a temporary tasks.json for testing.
func setupTest(t *testing.T) string {
	tmpDir := t.TempDir()
	oldTasksFile := tasksFile
	// Use a local variable to capture the correct path for this test run
	tasksFile = filepath.Join(tmpDir, "tasks.json")

	return oldTasksFile
}

// teardownTest restores the original tasksFile path.
func teardownTest(oldTasksFile string) {
	tasksFile = oldTasksFile
}

func TestAddTask(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	description := "Buy groceries"

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && (s == "os.Exit was called with code: 0" || s == "os.Exit was called with code: 1") {
				// Expected panic from mockExit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	addTask(description)
	output := stopCaptureOutput()

	expectedJSON := `{"id":1,"status":"added"}` + "\n"
	if output != expectedJSON {
		t.Errorf("addTask(%q) got %q, want %q", description, output, expectedJSON)
	}

	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("failed to load tasks after add: %v", err)
	}

	if len(tasks) != 1 || tasks[0].Description != description || tasks[0].ID != 1 || tasks[0].Done != false {
		t.Errorf("task not added correctly: %+v", tasks)
	}
}

func TestListTasks(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	// Add some tasks first
	_ = saveTasks([]Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: true},
		{ID: 3, Description: "Task 3", Done: false},
	})

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 0" {
				// Expected panic from mockExit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	listTasks()
	output := stopCaptureOutput()

	expectedTasks := []Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 3, Description: "Task 3", Done: false},
	}
	expectedJSONBytes, _ := json.Marshal(expectedTasks)
	expectedJSON := string(expectedJSONBytes) + "\n"

	if output != expectedJSON {
		t.Errorf("listTasks() got %q, want %q", output, expectedJSON)
	}
}

func TestCompleteTask(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	// Add some tasks first
	_ = saveTasks([]Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: false},
