func captureOutput() {
	mu.Lock()
	oldStdout = os.Stdout
	oldStderr = os.Stderr
	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w
	capturedStdout.Reset()
	go func() {
		defer r.Close()
		io.Copy(&capturedStdout, r)
	}()
	mu.Unlock()
}

// stopCaptureOutput restores stdout and returns the captured output.
func stopCaptureOutput() string {
	mu.Lock()
	defer mu.Unlock()
	// Close the writer to signal the goroutine to finish copying
	_ = os.Stdout.Close()
	_ = os.Stderr.Close()

	// Restore original stdout/stderr
	os.Stdout = oldStdout
	os.Stderr = oldStderr

	return capturedStdout.String()
